#[inductive(initialize)]
fn initialize_inductive(post: Self) { }

#[inductive(delete_key_value)]
fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
    broadcast use vstd::imap::group_imap_lemmas;
    broadcast use vstd::seq::group_seq_lemmas;
    assert forall |k: Key| imply(
        post.frag[k].is_some(),
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
                && (#[trigger] post.matrix[r][c as int]).is_some()
                && post.matrix[r][c as int].unwrap().0 == k
    ) by {
        if post.frag[k].is_some() {
            if k == key {
                assert(post.frag[k] == None);
                assert(false);
            } else {
            assert(pre.frag[k] == post.frag[k]);
            assert(pre.key_in_map_implies_key_in_matrix());
            let witness = choose |r: Row, c: Col|
                0 <= r < HEIGHT && 0 <= c < WIDTH
                    && (#[trigger] pre.matrix[r][c as int]).is_some()
                    && pre.matrix[r][c as int].unwrap().0 == k;
            let r = witness.0;
            let c = witness.1;
            if r == row && c == col {
                assert(pre.matrix[r][c as int].unwrap().0 == key);
                assert(false);
            } else {
                assert(post.matrix[r][c as int] == pre.matrix[r][c as int]);
                assert(post.matrix[r][c as int].is_some());
                assert(post.matrix[r][c as int].unwrap().0 == k);
            }
        }
        }
    };
}

